"""Build an evidence-backed individual report for subsequent team reconciliation."""
import json
from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import letter
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle

ROOT=Path(__file__).resolve().parent

def build():
    ev=ROOT/'outputs/evidence'
    load=lambda n:json.loads((ev/n).read_text(encoding='utf-8'))
    a=load('full_data_checks.json'); v=load('independent_validation.json')
    rep=load('reproducibility.json'); s=a['outputs']['summary']; m=a['merges']['bls_to_ca_claude']
    assert v['passed'] and rep['all_cleaned_outputs_identical'] and rep['notebook_executed']
    styles=getSampleStyleSheet()
    styles.add(ParagraphStyle(name='BodyCustom',fontName='Helvetica',fontSize=9.5,leading=13,spaceAfter=7))
    styles['Title'].textColor=colors.HexColor('#990000')
    styles['Heading2'].textColor=colors.HexColor('#990000')
    styles['Heading2'].fontSize=12
    story=[]
    def p(text,style='BodyCustom'):
        story.append(Paragraph(escape(str(text)),styles[style]))
    def item(n,title,status,text):
        p(f'{n}. {title} - {status}','Heading2'); p(text)
    def table(data,widths):
        t=Table([[Paragraph(escape(str(c)),styles['BodyCustom']) for c in row] for row in data],colWidths=widths,repeatRows=1)
        t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#f3e7e7')),
             ('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.5,colors.gray),
             ('BOTTOMPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5)]))
        story.append(t)
    p('Module 6 | Project Data Cleaning','Title')
    p('AI Workforce Investment Planner - Vision A','Heading2')
    p('Individual analyst: Yixiang Lu | GitHub: EthanLu917 | Branch: yixiang-lu')
    p('Prepared October 4, 2026 with Codex assistance. Individual evidence report for team reconciliation; this is not a claim that teammates have reviewed or reconciled these results.')
    p('Question: Which California OEWS area-occupation combinations warrant further review using published employment, median annual wages, and state-level observed Claude usage? These inputs support descriptive screening, not causal claims or an investment ranking.')
    table([['Verified output','Result'],['California area-occupation rows',f"{s['bls_rows']:,}"],
           ['Areas / distinct occupations',f"{s['areas']} / {s['occupations']}"],
           ['Selected Anthropic occupation-metric rows',f"{s['anthropic_rows']:,}"],
           ['Missing employment / median annual wage',f"{s['employment_missing']} / {s['wage_missing']}"],
           ['Rows with no published matching CA AI share',f"{s['unmatched_ai_rows']:,}"],
           ['Fresh notebook reproduction','Identical cleaned-file hashes']], [340,160])
    p('Read before using the result','Heading2')
    p('The joined AI share is repeated state-level context, not a local adoption estimate. The O*NET-to-SOC prefix mapping is provisional and must be verified before decision use. Missing AI cells are not zero. No priority score is calculated. Team reconciliation and the final Gradescope upload remain separate human steps.')
    p('Evidence location: outputs/evidence/. Full cleaned tables are regenerated by clean_data.py and included in the local ZIP; GitHub contains the 50-row sample and full-data evidence.')
    story.append(PageBreak())
    p('Checklist | Inspection and cleaning','Title')
    item(1,'State vision and question','Done','Vision A confirmed by the student. Compare published employment and annual median wages across California OEWS areas; use CA Claude occupation shares as separate context. See cleaning_plan.md. Business prioritization weights are not inferred.')
    item(2,'Define one row','Done','BLS: one area x detailed occupation, unique AREA + OCC_CODE after filtering. AEI: one product x period x geography x category x hierarchy x metric x node. Signals: one published grouping-key combination; key definitions are in full_data_checks.json. A repeated occupation identifier across areas/periods/metrics is valid.')
    item(3,'Preserve source','Done','Original files are opened read-only. source_manifest.json records SHA-256 and size for all seven original input files. BLS release: May 2025; AEI release: June 26, 2026; Signals package: local v2.0 package. Original retrieval dates are unknown; inspection was October 4, 2026. Hashes are checked again after execution.')
    item(4,'Inspect columns and types','Done','All selected original source rows were inspected. Strings preserve leading zeros, including nonmetro area IDs and NAICS 000000. Dates are checked against YYYY-MM-DD; numeric conversions reject unexpected tokens. All unexpected conversion failures are zero. BLS blank/*/**/# markers are recognized missing values, not failed numeric conversions. Raw markers and values remain alongside typed fields. See per-source conversion_failures, numeric_markers_full, missing_before and missing_after.')
    changes=sum(sum(x.get('text_changes',{}).values()) for x in a['sources'].values())
    examples=[x for q in a['sources'].values() for x in q.get('text_examples',[])]
    item(5,'Standardize text','Done',f'Boundary whitespace is trimmed without changing capitalization or punctuation. {changes:,} source cells changed. '+
         ('Examples: '+str(examples[:2]) if examples else 'No boundary-whitespace changes were needed; unchanged identifiers include 0600003 -> 0600003 and 000000 -> 000000.')+
         ' Source labels are retained in raw columns for traceability. See text_changes/text_examples in full_data_checks.json.')
    item(6,'Investigate duplicates','Done','Exact duplicate excess and full-key repetition counts are recorded separately for every source. All are zero in this run. Node IDs repeat legitimately across periods, metrics and geographies. No rows were deduplicated; unexpected logical-key collisions would stop execution.')
    item(7,'Handle missing data','Done',f"Final BLS employment has {s['employment_missing']} missing values; annual median wage has {s['wage_missing']}. Recognized suppression/top-code markers become numeric missing values, while raw tokens remain. No imputation or missing-driven row drops occur. {s['unmatched_ai_rows']:,} unmatched AI rows stay missing. Per-field before/after counts and marker counts appear in full_data_checks.json. Filling with zero would understate unknown values.")
    story.append(PageBreak())
    p('Checklist | Validation','Title')
    flags=sum(x.get('range_flag_count_full',x.get('range_flag_count_selected',0)) for x in a['sources'].values())
    item(8,'Check suspicious values','Done',f'All AEI values and dates were parsed and checked; percent bounds are 0-100 and autonomy bounds 1-5. Signals shares use 0-1. BLS selected numeric fields are checked for negative values. Range flags found: {flags}. Top-coded wages remain missing rather than using a fabricated exact wage. No outlier trimming is applied; unusual values are not automatically errors.')
    item(9,'Verify merges','Unresolved',f"The mechanical join passes many-to-one validation: {m['bls_before']:,} BLS rows become {m['joined_after']:,} joined rows, with no row multiplication. {m['aei_leaf_before']} CA leaf cells aggregate to {m['aei_prefix_after']} prefixes. {m['unmatched_bls_rows']:,} BLS rows ({m['unmatched_bls_codes']} codes) are unmatched; {m['unused_aei_prefixes']} AI prefixes have no selected BLS occupation. Exported unmatched tables document both sides. The prefix mapping is provisional, not a verified taxonomy crosswalk; this prevents final investment conclusions.")
    item(10,'Reconcile changes','Done',f"BLS originals contain 48,689 nonmetro and 150,023 metro rows. Declared geography/occupation filters retain 973 + 10,874 = {s['bls_rows']:,}; all exclusions are accounted for per workbook. AEI originals contain 2,128,278 rows; the documented occupation/geography scope retains {s['anthropic_rows']:,}. Four Signals files retain all 8,328 rows. Published BLS employment totals {s['employment_published_sum']:,.0f} before and after the join; this is a partial published detailed-occupation sum, not a complete state employment estimate. CA leaf share total {m['aei_share_before']:.2f}% is preserved by aggregation.")
    item(11,'Check calculations','Done',f"Employment sum uses {s['employment_n']:,} nonmissing rows; wage summaries use {s['wage_n']:,}. area_metric_support.csv reports group-specific denominators. Missing values are excluded from sums/means; group keys are retained with dropna=False. The average of occupation median wages is explicitly unweighted and is not an employee-level median. State AI shares are never summed over repeated areas. No cross-product/time averaging is used.")
    item(12,'Verify five records','Done',f"Independent validation checks every selected BLS row and its {v['numeric_columns_checked_per_row']} numeric columns against the original XLSX files. It also independently aggregates original CA AEI rows using Decimal and verifies every joined row. Five difficult examples follow and are saved in independent_validation.json.")
    item(13,'Test reproducibility','Done',f"The submitted notebook ran in a fresh kernel and reproduced all {rep['cleaned_files_compared']} cleaned files with identical SHA-256 hashes. The independent validator passed. See reproducibility.json, output_hashes.json and the executed cleaning.ipynb. Exact commands and environment dependencies are in README.md.")
    item(14,'Remaining limitations','Done','Documented limits: provisional taxonomy alignment; incomplete published AI cells; AI-use share differs from exposure/adoption; state AI values do not measure metro usage; BLS and AI vintages differ; published employment excludes suppressed cells; no causal outcome or ROI; team reconciliation pending. These limits constrain interpretation even when transformations are correct.')
    story.append(PageBreak())
    p('Cleaning decision log','Title')
    decisions=[('R1','Source preservation','Hash original files; no source edits. Retrieval date remains unknown.'),
       ('R2','Scope','CA detailed OEWS areas plus declared AEI occupation/geography scope and four Signals context tables.'),
       ('R3','Text and identifiers','Trim only boundary whitespace; retain meaningful labels and leading zeros.'),
       ('R4','Missing values','Convert recognized BLS markers to missing with raw markers retained; no zero fill.'),
       ('R5','Duplicates','Check exact rows and full keys separately; stop on collisions; remove none.'),
       ('R6','Geography and units','Keep product, date, geography and units visible; API remains global context.'),
       ('R7','Join','Aggregate same-period published CA leaf shares by SOC prefix; left join many-to-one; mapping provisional.'),
       ('R8','Unusual values','Check appropriate ranges; flag rather than drop or cap.'),
       ('R9','Validation/sample','Full-data assertions, independent source checks, deterministic difficult-case sample and fresh rerun.')]
    table([['Rule','Decision','Reason / effect']]+decisions,[35,110,355])
    p('The full pre-implementation plan and revision log are in cleaning_plan.md. No analytical rule was revised after observing results; implementation-only fixes are recorded there. These are Codex-assisted proposed choices, not evidence of team approval.')
    story.append(PageBreak())
    p('Five original-to-cleaned checks','Title')
    p('Values below are employment; annual median wage (USD); California Claude usage (%). Numeric display is rounded for readability; exact source/output values and comparisons are preserved in independent_validation.json.')
    def values(d):
        return '; '.join('missing' if d[c] is None else format(float(d[c]),'.10g')
                        for c in ['TOT_EMP','A_MEDIAN','ca_claude_usage_pct'])
    for i,r in enumerate(v['five_record_checks'],1):
        p(f"{i}. {r['AREA']} / {r['OCC_CODE']} - {r['occupation']}",'Heading2')
        p(f"Source: {r['source_file']}, data record {r['source_record']} (worksheet row = record + 1).")
        p('Original employment / wage: '+r['original']['TOT_EMP']+' / '+r['original']['A_MEDIAN'])
        p('Expected: '+values(r['expected'])+' | Actual: '+values(r['actual'])+' | MATCH')
        p(r['reason'])
    story.append(PageBreak())
    p('Codex verification response','Title')
    p('Verification performed by Codex on October 4, 2026. I executed the cleaning script, independently checked source-to-output transformations, and executed the notebook in a fresh kernel. Every declared source was inspected in full; the sample was not used as a substitute for full-data checks. All selected BLS rows were independently compared with the original workbook values, and every joined AI value was independently recomputed from the original AEI file. Cleaned output hashes matched on the notebook rerun.')
    p('What this verifies: the implemented rules reproduce the submitted outputs; identifiers, suppression markers, numeric values, row counts, join cardinality, and selected totals are consistent with original sources. What it does not verify: that the provisional occupation-prefix mapping is an official crosswalk, that a state usage share measures regional adoption, that cleaning choices have received student/team approval, or that these inputs establish pilot effectiveness. Those decisions remain with the analyst/team.')
    p('Team reconciliation / submission status','Heading2')
    p('Pending: compare each member\'s independent cleaning results, reconcile scope and mapping choices, approve the final group checklist, and upload the group PDF/ZIP to Gradescope. This report supplies individual evidence for that discussion. It does not assert reconciliation or Gradescope submission.')
    p('A preliminary comparison with Qiyue\'s published branch is in team_reconciliation.md. Both workflows report 11,847 BLS rows; the AI scopes and integrated row units differ. Matching BLS counts alone does not establish matching values or team agreement.')
    p('Source and access references','Heading2')
    for title,url in [
        ('Anthropic June 2026 schema and publication thresholds','https://huggingface.co/datasets/Anthropic/EconomicIndex/blob/main/release_2026_06_26/data_documentation.md'),
        ('BLS May 2025 OEWS tables','https://www.bls.gov/oes/2025/may/oes_2025_m.htm'),
        ('BLS original regional archive','https://www.bls.gov/oes/special.requests/oesm25ma.zip'),
        ('OpenAI Signals package and methodology','https://openai.com/signals/data-download/')]:
        p(title+': '+url)
    p('Anthropic Economic Index data attribution: Massenkoff et al., Anthropic Economic Index report: Cadences (June 26, 2026), CC-BY. OpenAI Signals: OpenAI, v2.0 local data package; consult its included README.pdf and download-page terms. BLS: U.S. Bureau of Labor Statistics, May 2025 OEWS. Preserve attribution when redistributing samples.')
    target=ROOT/'outputs/module6_individual_report.pdf'
    def footer(canvas,doc):
        canvas.setFont('Helvetica',8);canvas.setFillColor(colors.grey)
        canvas.drawString(48,25,'Yixiang Lu | Module 6 | Individual evidence; team reconciliation pending')
        canvas.drawRightString(564,25,str(doc.page))
    SimpleDocTemplate(str(target),pagesize=letter,rightMargin=48,leftMargin=48,
        topMargin=42,bottomMargin=44,title='Module 6 - Yixiang Lu - Individual Cleaning Evidence',
        author='Yixiang Lu (Codex-assisted)').build(story,onFirstPage=footer,onLaterPages=footer)
    print(target)

if __name__=='__main__': build()
